-- Connect to an empty Coffee database.
CREATE TABLE Kategoriya (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nazvanie VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE Klient (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fio VARCHAR(100) NOT NULL, telefon VARCHAR(20) UNIQUE, bonus INT DEFAULT 0 CHECK(bonus>=0), email VARCHAR(100) CHECK(email LIKE '%@%'));
CREATE TABLE Sotrudnik (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fio VARCHAR(100) NOT NULL, id_boss INT REFERENCES Sotrudnik(id));
CREATE TABLE Tovar (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nazvanie VARCHAR(100) NOT NULL UNIQUE, cena DECIMAL(10,2) NOT NULL CHECK(cena>0), id_kategoriya INT REFERENCES Kategoriya(id));
CREATE TABLE Zakaz (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_klient INT NOT NULL REFERENCES Klient(id), id_sotrudnik INT REFERENCES Sotrudnik(id), data DATE DEFAULT CURRENT_DATE NOT NULL, summa DECIMAL(10,2) NOT NULL CHECK(summa>=0));
CREATE TABLE Sostav_zakaza (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_zakaz INT NOT NULL REFERENCES Zakaz(id),id_tovar INT NOT NULL REFERENCES Tovar(id),qty INT NOT NULL CHECK(qty>0),price DECIMAL(10,2) NOT NULL CHECK(price>0));
